private static <T> void armRace(CompletionStage<T> stage, int id, AtomicInteger winner,
        IntConsumer thenAcceptor, CompletableFuture<T> result) {
    stage.whenComplete((v, e) -> {
        if (winner.compareAndSet(0, id)) {
            try {
                thenAcceptor.accept(id);
            } catch (Throwable ex) {
                // A throwing acceptor must not strand the result: the loser's CAS has
                // already failed, so complete it here instead of hanging forever.
                Exceptions.throwIfFatal(ex);
                if (e != null) {
                    ex.addSuppressed(e);
                }
                result.completeExceptionally(ex);
                return;
            }
            if (e != null) {
                result.completeExceptionally(e);
            } else {
                result.complete(v);
            }
        }
    });
}

